with ranked as (select *, row_number() over (partition by order_id, carrier order by delivered_date desc nulls first, id) as rank_in_group from shipments qualify rank_in_group = 1) select case when cost >= 104 then 'HIGH' else 'LOW' end as cost_tier, count(case when status = 'DELIVERED' then 1 end) as delivered_count, sum(case when carrier = 'DHL' then cost else 0 end) as dhl_cost, round(avg(cost), 2) as avg_cost, count(*) as row_count, stddev_samp(cost) as cost_stddev from ranked group by cost_tier
